"""Authored wavelength at a stationary interface, including autonomous phase-speed case."""
from .vector_geometry_authoring import assemble_family,write_family
SOURCE_PATH='packages/engine/lessonos/study/content/physics-semestre-2026-bank/questions/U7-01.json'
SCENE='Una radiazione monocromatica di lunghezza d’onda nel vuoto λ₀>0 entra in un mezzo trasparente fermo, attraverso un’interfaccia stazionaria. L’indice di fase n è finito e n≥1; alla frequenza considerata v_fase=c/n. La frequenza f resta quella della sorgente durante ciascun passaggio: f=c/λ₀ e λ=v_fase/f. Fra preparazioni si possono cambiare sorgente o mezzo, sempre nel dominio dichiarato. '
TASKS=[
('La frequenza resta, la distanza fra le creste cambia',SCENE+'Con λ₀=600 nm e n=2, quanto vale λ in nm?',300,
 'Nel vuoto c=λ₀f; nel mezzo v_fase=λf. La stessa f permette di dividere le due relazioni: λ/λ₀=v_fase/c=1/n. Quindi λ=600 nm/2=300 nm. La lunghezza d’onda più corta non indica che la sorgente abbia cambiato frequenza all’interfaccia.',
 r'\lambda=\frac{v_{\rm fase}}f\qquad \lambda=\frac{\lambda_0}{n}\qquad \lambda=300\,\mathrm{nm}',
 '1200 nm moltiplica per n invece di dividere.600 nm conserva la lunghezza anziché la frequenza;150 nm divide due volte. Il valore zero non segue da indice finito e λ₀ positiva.',
 'Confronta le due relazioni velocità=lunghezza d’onda per frequenza.'),
('La lunghezza conserva la propria dimensione',SCENE+'Quale unità misura λ?',['nm','Hz','m/s','1','s'],
 'λ è una distanza. Il nanometro è un’unità di lunghezza:1 nm=10⁻⁹ m. Dividere λ₀ per n, che è un numero puro, conserva questa dimensione. La frequenza resta una grandezza distinta.',
 r'1\,\mathrm{nm}=10^{-9}\,\mathrm m\qquad [n]=1\qquad [\lambda]=\mathrm m',
 'Hz misura f, m/s la velocità di fase, s il periodo. Il simbolo 1 indica una quantità pura come n, non la lunghezza λ.',
 'L’indice non aggiunge un’unità alla lunghezza.'),
('Che cosa attraversa l’interfaccia senza cambiare','Caso autonomo: luce monocromatica passa dall’aria a un vetro trasparente fermo attraverso un’interfaccia stazionaria. Quale grandezza resta invariata nel passaggio?',['La frequenza','La lunghezza d’onda','La velocità di fase','Sempre l’intensità trasmessa','Sempre l’ampiezza del campo elettrico'],
 'La continuità temporale dell’oscillazione all’interfaccia ferma impone la stessa frequenza sui due lati. Velocità di fase e lunghezza d’onda cambiano con il mezzo. Intensità e ampiezza trasmesse non sono in generale invarianti: possono intervenire riflessione e differente impedenza ottica, anche in assenza di assorbimento.',
 r'f_{\rm aria}=f_{\rm vetro}\qquad \lambda=\frac{v_{\rm fase}}f',
 'Conservare λ insieme a f imporrebbe la stessa velocità, contrariamente al cambio di indice. Trasparente non significa trasmissione di tutta l’intensità senza riflessione. L’ampiezza non è la frequenza.',
 'Pensa al ritmo imposto dalla sorgente a un confine fermo.'),
('Velocità di fase da un indice assegnato','Caso autonomo: un mezzo trasparente ha n=3/2. Si assume c=3 × 10⁸ m/s. Secondo n=c/v_fase, quanto vale la velocità di fase?',['2 × 10⁸ m/s','(9/2)× 10⁸ m/s','3 × 10⁸ m/s','(3/2)× 10⁸ m/s','0 m/s'],
 'Moltiplico n=c/v_fase per v_fase e divido per n>0: v_fase=c/n. Dividere per 3/2 equivale a moltiplicare per 2/3. I tre del numeratore e del divisore si cancellano e resta 2 × 10⁸ m/s. Qui non si chiede una velocità di gruppo o una velocità di particelle materiali.',
 r'v_{\rm fase}=\frac cn\qquad v_{\rm fase}=\frac23c\qquad v_{\rm fase}=2\cdot10^8\,\mathrm{m/s}',
 '(9/2)× 10⁸ m/s moltiplica c per n.3 × 10⁸ ignora il mezzo; (3/2)× 10⁸ copia il numero dell’indice nella velocità. Zero non segue da n finito.',
 'L’indice maggiore di uno riduce la velocità di fase rispetto a c.'),
('La lunghezza nel vuoto da quella nel mezzo',SCENE+'Si misurano λ=300 nm e n=2. Quanto vale λ₀ in nm?',600,
 'Moltiplico λ=λ₀/n per n: λ₀=nλ. Due per 300 nm restituisce 600 nm. È la lunghezza della stessa radiazione nel vuoto, non un’ulteriore lunghezza nel vetro.',
 r'\lambda_0=n\lambda\qquad \lambda_0=600\,\mathrm{nm}',
 '150 nm divide ancora per n;300 nm ignora l’indice.1200 nm applica due volte la moltiplicazione. La sostituzione 600/2=300 nm ricostruisce il dato.',
 'Nell’inversa devi annullare la divisione per n.'),
('L’indice da due lunghezze',SCENE+'λ₀=600 nm e λ=300 nm. Quanto vale n?',2,
 'Isolo n=λ₀/λ. Le unità nm si cancellano e il rapporto 600/300=2 è puro. Il dominio n≥1 richiede λ≤λ₀: una misura λ>λ₀ non sarebbe ammessa nel modello dichiarato.',
 r'n=\frac{\lambda_0}{\lambda}\qquad n=2',
 'Un mezzo inverte il rapporto e viola n≥1.300 o 600 copiano una lunghezza invece di formare un rapporto. Non occorre una radice.',
 'Controlla prima che il rapporto rispetti il dominio dell’indice.'),
('Un indice minore, stessa sorgente',SCENE+'A usa λ₀=600 nm, n=2. B mantiene λ₀ e usa n=3/2. Quanto vale λ_B/λ_A?',['4/3','3/4','2','1/2','1'],
 'A dà 300 nm. In B dividere 600 per 3/2 significa 600·2/3=400 nm. Il rapporto finale/iniziale è 400/300=4/3. Entrambi gli indici rispettano n≥1 e la sorgente è la stessa in queste due prove.',
 r'\lambda_A=300\,\mathrm{nm}\qquad \lambda_B=400\,\mathrm{nm}\qquad \lambda_B/\lambda_A=\frac43',
 '3/4 segue il rapporto degli indici senza invertirlo. Due o mezzo non usano n_B=3/2; uno ignora il cambio di mezzo.',
 'La lunghezza nel mezzo è inversa all’indice a sorgente fissata.'),
('Uno scarto espresso in nanometri',SCENE+'Con λ₀=600 nm, n=2 si propone λ=600 nm. Quanto vale proposta meno corretto?',['300 nm','−300 nm','2','600 nm','0 nm'],
 'La lunghezza corretta è 300 nm. La proposta supera il risultato di 600−300=300 nm. Il rapporto è invece due, senza unità, e non è la grandezza richiesta.',
 r'\lambda=300\,\mathrm{nm}\qquad e=(600-300)\,\mathrm{nm}\qquad e=300\,\mathrm{nm}',
 '−300 cambia l’ordine della sottrazione; due risponde con il rapporto;600 copia la proposta. Zero accetta una lunghezza che non soddisfa λ=λ₀/n.',
 'Ricava il valore nel mezzo prima di sottrarre.'),
('L’inversa simbolica mantiene n',SCENE+'λ e n sono noti. Quale relazione isola λ₀?',['λ₀ = n λ','λ₀ = λ / n','λ₀ = n / λ','λ₀ = n λ²','λ₀ = λ − n'],
 'Dalla relazione λn=λ₀ segue direttamente λ₀=nλ. n è puro e la dimensione rimane una lunghezza. L’inversa vale nel dominio λ>0, n≥1 della preparazione.',
 r'n\lambda=\lambda_0\qquad \lambda_0=n\lambda',
 'λ/n ripete la legge diretta. n/λ ha dimensione inversa di lunghezza; nλ² ha dimensione di area. λ−n sottrae una lunghezza a un numero puro.',
 'Moltiplica entrambi i membri della legge diretta per n.'),
('Sorgente e mezzo cambiano fra preparazioni',SCENE+'Fra prove λ₀, B=κ₁λ₀, A e n_B=κ₂n_A, con fattori positivi e n_A, n_B≥1. Quanto vale λ_B/λ_A?',['κ₁ / κ₂','κ₁ κ₂','κ₂ / κ₁','κ₁ / κ₂²','κ₁ + κ₂'],
 'La nuova lunghezza nel vuoto moltiplica il numeratore e l’indice il denominatore. Nel rapporto restaκ₁/κ₂. Se cambia λ₀ può cambiare la sorgente fra le prove: la frequenza resta invariata solo attraverso ciascuna interfaccia stazionaria, non necessariamente fra sorgenti differenti.',
 r'\lambda_B=\frac{\kappa_1\lambda_{0,A}}{\kappa_2n_A}\qquad \lambda_B/\lambda_A=\kappa_1/\kappa_2',
 'Il prodotto rende diretta la dipendenza da n; il reciproco scambia i ruoli e il quadrato di κ₂ non appartiene alla legge. La somma darebbe due per preparazioni identiche. κ₂ può essere minore di uno, purché κ₂n_A≥1.',
 'Mantieni il vincolo sull’indice finale, non imporre arbitrariamente κ₂≥1.'),
('Due variazioni che allungano λ',SCENE+'A ha λ₀=600 nm, n=2. B ha λ₀=800 nm, n=3/2. Quanto vale λ_B/λ_A?',['16/9','9/16','4/3','3/4','1'],
 'A dà 300 nm. B dà 800·2/3=1600/3 nm. Il rapporto è(1600/3)/300=16/9: il fattore 4/3 della lunghezza nel vuoto si moltiplica per il fattore inverso 4/3 dell’indice.',
 r'\lambda_A=300\,\mathrm{nm}\qquad \lambda_B=\frac{1600}{3}\,\mathrm{nm}\qquad \lambda_B/\lambda_A=\frac{16}{9}',
 '9/16 inverte il confronto.4/3 segue solo uno dei due effetti, 3/4 il rapporto diretto degli indici. Uno presume una compensazione invece del rinforzo.',
 'Tieni la frazione 1600/3 esatta, senza decimali.'),
('Media delle due lunghezze nel mezzo',SCENE+'Si mediano con uguale peso A:λ₀=600 nm, n=2 e B:λ₀=800 nm, n=3/2. Quanto vale la media di λ?',['1250/3 nm','400 nm','2500/3 nm','350/3 nm','1600/3 nm'],
 'Le uscite sono 300 e 1600/3 nm. Scrivo 300=900/3, sommo 2500/3 e dimezzo: media 1250/3 nm. Agli ingressi medi λ₀700 nm, n 7/4 il modello darebbe 400 nm, inferiore alla media delle uscite di 50/3 nm. Nessuna approssimazione è necessaria.',
 r'\overline\lambda=\frac{300+1600/3}{2}\,\mathrm{nm}\qquad \overline\lambda=\frac{1250}{3}\,\mathrm{nm}\qquad \lambda_{\rm dati\ medi}=400\,\mathrm{nm}',
 '400 nm usa gli ingressi medi;2500/3 è la somma senza dimezzare;350/3 è la semidifferenza.1600/3 ripete soltanto la seconda lettura. La media statistica non è una nuova interfaccia attraversata in successione.',
 'Usa il denominatore comune tre prima di dividere per due.'),
('Quale indice per il bersaglio',SCENE+'A ha λ₀, A=600 nm, n_A=2. B usa λ₀, B=800 nm e deve dare λ_B=(16/9)λ_A. Quanto vale n_B/n_A?',['3/4','4/3','16/9','9/16','1'],
 'Il bersaglio è(16/9)·300=1600/3 nm. L’inversa dà n_B=800/(1600/3)=3/2, che rispetta n≥1. Divido per n_A 2 e ottengo 3/4. Il fattore dell’indice non coincide con quello della lunghezza.',
 r'\lambda_B=\frac{1600}{3}\,\mathrm{nm}\qquad n_B=\frac32\qquad n_B/n_A=\frac34',
 '4/3 inverte il rapporto.16/9 copia il bersaglio di λ e 9/16 il suo reciproco. Un indice invariato darebbe 400 nm nella seconda prova, non 1600/3 nm.',
 'Prima ricava la lunghezza bersaglio, poi isola n_B.'),
('Un display continuo prima dell’inversa',SCENE+'Il display continuo adimensionale D=a_cal λ, senza offset, legge 900 per λ₀=600 nm, n=2. Nella nuova prova D=1600, n=3/2. Quanto vale λ₀ nuova in nm?',800,
 'Il riferimento ha λ 300 nm: a_cal=900/(300 nm)=3 nm⁻¹. D 1600 decodifica λ 1600/3 nm. Moltiplicando per n 3/2, i tre si cancellano e λ₀=800 nm. Non occorre arrotondare la lettura frazionaria di lunghezza.',
 r'a_{\rm cal}=3\,\mathrm{nm^{-1}}\qquad \lambda=\frac{1600}{3}\,\mathrm{nm}\qquad \lambda_0=800\,\mathrm{nm}',
 '2400 nm usa il display come lunghezza e poi moltiplica per n.1600 nm si ferma alla lettura senza tararla;600 nm ripete il riferimento. La lettura non è un conteggio di lunghezze intere.',
 'Decodifica λ prima della moltiplicazione per l’indice.'),
('Due riferimenti separano il guadagno dallo zero',SCENE+'D=a_cal λ+b_cal è un display continuo. A:λ₀=600 nm, n=2, D=601. B:λ₀=800 nm, n=3/2, D=3203/3. C:n=2, D=801. Quanto vale λ₀, C in nm?',800,
 'Le lunghezze di riferimento sono 300 e 1600/3 nm. La differenza di letture è(3203−1803)/3=1400/3, mentre quella fisica è(1600−900)/3=700/3 nm. Il rapporto dà a_cal 2 nm⁻¹ e b_cal 1. La lettura 801 indica λ_C 400 nm, quindi λ₀, C 800 nm.',
 r'a_{\rm cal}=2\,\mathrm{nm^{-1}}\qquad b_{\rm cal}=1\qquad \lambda_C=400\,\mathrm{nm}\qquad \lambda_{0,C}=800\,\mathrm{nm}',
 'Il valore 801 nm omette la sottrazione dell’offset: usando λ₀=801 nm si avrebbe D=802, non 801. Il valore 1600 nm sottrae l’offset ma omette la divisione per il guadagno. Il valore 400 nm è la lunghezza nel mezzo; occorre ancora moltiplicarla per n=2 per tornare alla lunghezza nel vuoto.',
 'Le differenze eliminano l’offset e mantengono frazioni esatte.'),
('Una misura che non fissa l’indice',SCENE+'Fra preparazioni λ₀=(300 nm)n e si misura anche λ=300 nm. Quante coppie (λ₀, n) sono possibili nel dominio n≥1?',['Infinite coppie continue','Una sola coppia','Due sole coppie','Nessuna coppia','Solo coppie con n intero'],
 'Inserendo il vincolo in λ=λ₀/n si ottiene sempre 300 nm. La misura è ridondante: n 1 con λ₀300 nm e n 2 con λ₀600 nm sono due esempi, ma tutti gli n reali finiti almeno uno danno una coppia. Non è un conteggio di fotoni e n non è imposto intero.',
 r'\lambda_0=(300\,\mathrm{nm})n\qquad \lambda=300\,\mathrm{nm}\qquad (\lambda_0,n)=(300\,\mathrm{nm},1)',
 'Una o due coppie richiederebbero un altro vincolo indipendente. La risposta “Nessuna coppia” è smentita dagli esempi. Imporre indici interi non è previsto dal modello e perderebbe soluzioni ammesse.',
 'Controlla se λ si semplifica dopo la sostituzione.')]
CHOICES={n:0 for n in[2,3,4,7,8,9,10,11,12,13,16]}
UNITS={1:'nm',5:'nm',6:'1',14:'nm',15:'nm'}
FIGURES={1:'I fronti di fase nella prima tappa sono disegnati alla stessa scala spaziale: λ₀=600 nm nel vuoto e λ=300 nm nel mezzo con n=2. La frequenza resta uguale attraverso l’interfaccia ferma; le righe mostrano regioni distinte, non istanti successivi.',12:'Le barre alla stessa scala rappresentano 300 nm, 1600/3 nm e la loro media 1250/3 nm. Appartengono alle due preparazioni dichiarate; la frequenza è conservata durante ogni passaggio, ma le sorgenti fra prove possono essere diverse.',9:'L’ultimo grafico mantiene n=2: λ è lineare in λ₀. Il punto 600 nm, 300 nm ricostruisce il riferimento; l’origine è soltanto il limite, escluso dal dominio λ₀>0.'}
def assemble(repo,source_ref):
 return assemble_family(repo,source_ref,'wavelength-in-medium',TASKS,CHOICES,UNITS,'wavelength-in-medium-progressive.svg',FIGURES,24000,course='C5',unit='u7',source_path=SOURCE_PATH,skill='C5-L06',prerequisites=['C1-L001','C1-L002','C5-L02','C5-L04','C5-L06'],section='Frequenza conservata e lunghezza d’onda nel mezzo',coverage=['Interfaccia stazionaria e velocità di fase','Unità, inverse e dominio n≥1','Medie e display continui','Caso autonomo della velocità di fase'])
if __name__=='__main__':write_family(assemble,'wavelength-in-medium-240')
